"use client";
import { apiFetch } from "@/src/lib/ayni-api-fetch";

import { useCallback, useEffect, useState } from "react";
import { ArrowRight, Check, ChevronDown, Sparkles } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { localDatabaseApiUrl } from "@/src/lib/local-database";
import { FamilyReportGenerator } from "./family-report-generator";
import { PedagogicalCoverage } from "./pedagogical-coverage";
import { AYNI_HEURISTICS } from "@/src/lib/ayni-heuristics.mjs";
import { diagnosticAntecedentLabel, periodEvidenceLabel } from "@/src/lib/record-language";
import { AssessmentMasterPanel } from "./assessment-master-panel";
import { newAyniFeatureEnabled } from "@/src/lib/new-ayni-feature-flag.mjs";
import { CompetencyPeriodReview } from "./competency-period-review";
import { PeriodBatchPanel } from "./period-batch-panel";
import { PeriodConsolidated } from "./period-consolidated";
import { readWorkspaceParams, useWorkspaceSubview, writeWorkspaceLocation } from "@/src/lib/workspace-location";

type Year = { id: string; year: number };
type Classroom = { id: string; school_year_id: string; section: string; age: number };
type Period = { id: string; school_year_id: string; kind: "bimester" | "trimester"; ordinal: number; label: string; starts_on: string; ends_on: string };
type Student = { id: string; first_name: string; last_name: string; preferred_name: string | null };
type Row = { student_id: string; competency_id: string; competency_name: string; short_label:string; area:string; evidence_count: number; valuation_confirmed:boolean; level: string | null; conclusion: string | null; state: string };
type Overview = { students: Student[]; scope: { id: string; name: string;short_label?:string;area?:string }[]; available_competencies: { id: string; name: string }[]; rows: Row[]; closure_steps:{number:number;label:string;done:boolean}[]; siagie_export:{implemented:boolean;label:string;message:string}; statistics:{competencies:{competency_id:string;short_label:string;area:string;state:string;levels:Record<string,number>;evaluated:number;students_without_grade:number;students_without_evidence:number;activity_count:number;criterion_count:number;evidence_count:number;evidence_coverage:number}[];classroom:{pending_assessments:number;confirmed_assessments:number;total_assessments:number}}; progress: { students_complete: number; students_total: number; competencies_complete: number; competencies_resolved:number; competencies_total: number; observation_pending:number;review_pending:number;annual_unvalued:number|null }; closure: { closed: boolean; current: boolean;current_version_id:string|null;source_fingerprint:string } };
type TimelineItem = { id: string; observed_on: string; registered_at: string; activity_id: string; activity_title: string; criterion_id: string; criterion_text: string; performance_id: string | null; observation_text: string | null; media_available: boolean };
type DiagnosticAntecedent = { id: string; observed_on: string; situation_title: string; criterion_text: string | null; observation_text: string | null; source_type: string };
type Detail = { classroom_id: string; period_id: string; student_id: string; competency_id: string; state: string; evidence_count: number; diagnostic_antecedents: DiagnosticAntecedent[]; evidence_fingerprint: string; timeline: TimelineItem[]; reference: { kind: "official"; items: { id: string; official_text: string; source_ref: string }[] } | { kind: "cycle_standard"; competency: string; capacities: string[]; standard_summary: string; age_performance: null }; assessment: { achievement_level: string | null; teacher_justification: string | null; details: { evidence_overview?: string; information_status?: "sufficient" | "insufficient"; insufficiency_reason?: string | null } } | null; draft: { id:string;revision:number; current:boolean; teacher_analysis:string; conclusion_text:string; provisional_level:string|null; teacher_justification:string; details:{ information_status:"sufficient"|"insufficient"; evidence_overview:string; insufficiency_reason:string|null } } | null; insufficiency_reason: string | null; conclusion: string | null };
type Workspace = { years: Year[]; classrooms: Classroom[]; periods: Period[] };
type Suggestion = { generation_id: string; evidence_fingerprint: string; analysis: { information_status: "sufficient" | "insufficient"; evidence_overview: string; insufficiency_reason: string | null }; conclusion: null };
type ConclusionProposal = { competency_id:string;information_status:"sufficient"|"insufficient";conclusion_text:string;progress_examples:string[];support_or_conditions:string[];next_steps:string[];insufficiency_reason:string|null;caution:string };
type Consolidated = { rows: { student_id: string; student_name: string; competency_id: string; competency_name: string; achievement_level: string | null; conclusion: string; state: string }[] };
type ClassroomReportDetails={general_overview:string;developed_competencies:string[];group_strengths:string[];competencies_needing_development:string[];little_or_not_worked:string[];evidence_coverage:string;follow_up_summary:string;next_period_findings:string[]};

const stateText: Record<string, string> = { confirmed: "Valoración confirmada", needs_review: "Requiere revisión", level_pending: "Falta nivel", conclusion_pending: "Falta conclusión", observation_pending:"Pendiente de observación", no_evidence: "Sin evidencias en este período", insufficient_information: "Evidencia insuficiente · borrador", draft:"Borrador guardado", pending: "Pendiente de revisión docente" };
const formSnapshot=(analysis:string,level:string,conclusion:string,justification:string)=>JSON.stringify({analysis:analysis.trim(),level,conclusion:conclusion.trim(),justification:justification.trim()});
const studentName = (student: Student) => [student.preferred_name || student.first_name, student.last_name].filter(Boolean).join(" ");
const formatDate = (date: string) => new Date(`${date.slice(0, 10)}T12:00:00`).toLocaleDateString("es-PE");

async function api<T>(path: string, body?: unknown): Promise<T> {
  const response = await apiFetch(`${localDatabaseApiUrl}${path}`, { method: body === undefined ? "GET" : "POST", headers: body === undefined ? undefined : { "content-type": "application/json" }, body: body === undefined ? undefined : JSON.stringify(body), cache: "no-store" });
  const payload = await response.json() as T & { error?: string;message?:string };
  if (!response.ok) throw new Error(payload.message??payload.error ?? "No se pudo completar la acción.");
  return payload;
}

const periodViews = ["student", "conclusions", "classroom", "report", "family", "coverage", "consolidated"] as const;
const periodFocuses = ["none", "conclusion"] as const;
export function PeriodEvaluation({ initialStudentId = "", initialCompetencyId = "", initialView = "student", onPlan, onPrepareActivity }: { initialStudentId?: string; initialCompetencyId?: string; initialView?: "student" | "conclusions" | "family" | "coverage" | "consolidated"; onPlan?:()=>void; onPrepareActivity?:()=>void }) {
  const [workspace, setWorkspace] = useState<Workspace | null>(null);
  const [yearId, setYearId] = useState("");
  const [classroomId, setClassroomId] = useState("");
  const [periodId, setPeriodId] = useState("");
  const [studentId, setStudentId] = useState(initialStudentId);
  const [competencyId, setCompetencyId] = useState(initialCompetencyId);
  const [overview, setOverview] = useState<Overview | null>(null);
  const [overviewError, setOverviewError] = useState("");
  const [overviewRetry, setOverviewRetry] = useState(0);
  const [detail, setDetail] = useState<Detail | null>(null);
  const [view, setView] = useWorkspaceSubview("Evaluar", "view", periodViews, initialView);
  const [focus, setFocus] = useWorkspaceSubview("Evaluar", "focus", periodFocuses, "none");
  useEffect(() => {
    if (view === "student" && focus === "conclusion" && detail?.student_id === studentId && detail?.competency_id === competencyId) {
      const target = document.getElementById("period-conclusion"); target?.scrollIntoView({ block: "center" }); target?.focus({ preventScroll: true });
    }
  }, [view, focus, detail, studentId, competencyId]);
  const [showSustento, setShowSustento] = useState(false);
  const [teacherAnalysis, setTeacherAnalysis] = useState("");
  const [achievementLevel, setAchievementLevel] = useState("");
  const [conclusionText, setConclusionText] = useState("");
  const [teacherJustification, setTeacherJustification] = useState("");
  const [savedDraftSnapshot, setSavedDraftSnapshot] = useState<string | null>(null);
  const [suggestion, setSuggestion] = useState<Suggestion | null>(null);
  const [conclusionGenerationId,setConclusionGenerationId]=useState("");
  const [conclusionProposal,setConclusionProposal]=useState<ConclusionProposal|null>(null);
  const [writingConclusion,setWritingConclusion]=useState(false);
  const [addingCompetencyId, setAddingCompetencyId] = useState("");
  const [excludingId, setExcludingId] = useState("");
  const [exclusionReason, setExclusionReason] = useState("");
  const [report, setReport] = useState<Consolidated | null>(null);
  const [classroomStudentFilter, setClassroomStudentFilter] = useState("");
  const [classroomCompetencyFilter, setClassroomCompetencyFilter] = useState("");
  const [classroomStatusFilter, setClassroomStatusFilter] = useState("");
  const [classroomAreaFilter,setClassroomAreaFilter]=useState("");
  const [classroomReport,setClassroomReport]=useState<{generation_id?:string;proposal?:ClassroomReportDetails;current?:{details:ClassroomReportDetails;status:string;stale?:boolean}|null;statistics?:Overview["statistics"]}|null>(null);
  const [message, setMessage] = useState("");
  const [busy, setBusy] = useState(false);
  const [assessmentMasterReady,setAssessmentMasterReady]=useState(false);
  const [reopenReason,setReopenReason]=useState("");
  const [reviewPair,setReviewPair]=useState({studentId:initialStudentId,competencyId:initialCompetencyId});

  useEffect(() => { void api<Workspace>("/api/period-evaluations/workspace").then((result) => {
    setWorkspace(result);
    const params = readWorkspaceParams("Evaluar");
    const year = result.years.find((item) => item.id === params.get("year")) ?? result.years[0], classroom = result.classrooms.find((item) => item.id === params.get("classroom") && item.school_year_id === year?.id) ?? result.classrooms.find((item) => item.school_year_id === year?.id);
    const periods = result.periods.filter((item) => item.school_year_id === year?.id);
    const today = new Date().toISOString().slice(0, 10);
    setYearId(year?.id ?? ""); setClassroomId(classroom?.id ?? ""); setPeriodId(periods.find((item) => item.id === params.get("period"))?.id ?? periods.find((item) => item.starts_on <= today && item.ends_on >= today)?.id ?? periods[0]?.id ?? "");
    setStudentId(params.get("student") ?? initialStudentId); setCompetencyId(params.get("competency") ?? initialCompetencyId);
  }).catch((error) => setMessage(error.message)); }, [initialStudentId, initialCompetencyId]);

  const applyOverview = useCallback((result: Overview) => {
    setOverviewError("");
    setOverview(result);
    setReport(null);
    setStudentId((current) => result.students.some((student) => student.id === current) ? current : result.students[0]?.id ?? "");
    setCompetencyId((current) => result.scope.some((item) => item.id === current) ? current : result.scope[0]?.id ?? "");
  }, []);
  useEffect(() => {
    if (yearId && classroomId && periodId) writeWorkspaceLocation("Evaluar", { year: yearId, classroom: classroomId, period: periodId, student: studentId, competency: competencyId }, true);
  }, [yearId, classroomId, periodId, studentId, competencyId]);
  async function reloadOverview() {
    if (!classroomId || !periodId) return;
    applyOverview(await api<Overview>(`/api/period-evaluations/overview?classroomId=${classroomId}&periodId=${periodId}`));
  }
  useEffect(() => {
    if (!classroomId || !periodId) return;
    let active = true;
    void api<Overview>(`/api/period-evaluations/overview?classroomId=${classroomId}&periodId=${periodId}`).then((result) => { if (active) applyOverview(result); }).catch((error) => { if (active) setOverviewError(error instanceof Error ? error.message : "No se pudieron cargar los registros."); });
    return () => { active = false; };
  }, [classroomId, periodId, overviewRetry, applyOverview]);

  function applyDetail(result: Detail) {
    setDetail(result); setShowSustento(false);
    const draft=result.draft,analysis=draft?.teacher_analysis ?? (result.state === "needs_review" ? "" : result.assessment?.details?.evidence_overview ?? "");
    const level=draft?.provisional_level ?? (result.state === "needs_review" ? "" : result.assessment?.achievement_level ?? "");
    const conclusion=draft?.conclusion_text ?? (result.state === "needs_review" ? "" : result.conclusion ?? "");
    const justification=draft?.teacher_justification ?? "";
    setTeacherAnalysis(analysis); setAchievementLevel(level); setConclusionText(conclusion); setTeacherJustification(justification);
    setSavedDraftSnapshot(draft?.current ? formSnapshot(analysis,level,conclusion,justification) : null);
    setConclusionGenerationId("");
    setConclusionProposal(null);
    setWritingConclusion(false);
    setSuggestion(draft?.current ? {generation_id:"",evidence_fingerprint:result.evidence_fingerprint,analysis:draft.details,conclusion:null} : null);
  }
  async function reloadDetail() {
    if (!classroomId || !periodId || !studentId || !competencyId || !overview?.students.some((student) => student.id === studentId) || !overview.scope.some((item) => item.id === competencyId)) return;
    applyDetail(await api<Detail>(`/api/period-evaluations/detail?classroomId=${classroomId}&periodId=${periodId}&studentId=${studentId}&competencyId=${competencyId}`));
  }
  useEffect(() => {
    if (!classroomId || !periodId || !studentId || !competencyId) return;
    let active = true;
    void api<Detail>(`/api/period-evaluations/detail?classroomId=${classroomId}&periodId=${periodId}&studentId=${studentId}&competencyId=${competencyId}`).then((result) => { if (active) applyDetail(result); }).catch((error) => { if (active) { setDetail(null); setMessage(error.message); } });
    return () => { active = false; };
  }, [classroomId, periodId, studentId, competencyId, overview]);

  async function act(work: () => Promise<void>) { setBusy(true); setMessage(""); try { await work(); } catch (error) { setMessage(error instanceof Error ? error.message : "Ocurrió un problema."); } finally { setBusy(false); } }
  const classrooms = workspace?.classrooms.filter((item) => item.school_year_id === yearId) ?? [];
  const periods = workspace?.periods.filter((item) => item.school_year_id === yearId) ?? [];
  const selectedStudent = overview?.students.find((item) => item.id === studentId);
  const selectedCompetency = overview?.scope.find((item) => item.id === competencyId);
  const studentRows = overview?.rows.filter((item) => item.student_id === studentId) ?? [];
  const missing = overview?.available_competencies.filter((item) => !overview.scope.some((scope) => scope.id === item.id)) ?? [];
  const currentPeriod = periods.find((item) => item.id === periodId);
  const closureReady = overview && overview.progress.competencies_total > 0 && overview.progress.competencies_resolved === overview.progress.competencies_total && (overview.progress.annual_unvalued === null || overview.progress.annual_unvalued === 0);
  const classroomAreas=[...new Set((overview?.rows??[]).map((row)=>row.area))].sort();
  const visibleStudents=(overview?.students??[]).filter((student)=>!classroomStudentFilter||student.id===classroomStudentFilter);
  const visibleScope=(overview?.scope??[]).filter((scope)=>{
    const sample=overview?.rows.find((row)=>row.competency_id===scope.id);return (!classroomCompetencyFilter||scope.id===classroomCompetencyFilter)&&(!classroomAreaFilter||sample?.area===classroomAreaFilter);
  });
  const hasUnsavedDraft=formSnapshot(teacherAnalysis,achievementLevel,conclusionText,teacherJustification)!==savedDraftSnapshot;
  const assessmentReadOnly=Boolean(detail?.assessment?.achievement_level && !detail.draft && detail.state !== "needs_review");

  if (!workspace) return <p className="rounded-2xl border bg-white p-6">{message || "Cargando evaluación del período…"}</p>;
  if(process.env.NEXT_PUBLIC_AYNI_EXPERIENCE!=="0"&&["student","conclusions","family","consolidated"].includes(view))return <section className="mx-auto max-w-5xl space-y-6">
    <header><h1 className="text-2xl font-bold">{view==="family"?"Informe a familias":view==="consolidated"?"Consolidado":"Evaluación del bimestre"}</h1><label className="mt-3 block text-sm font-semibold">Período<select className="mt-1 min-h-11 w-full rounded-xl border bg-white px-3" value={periodId} onChange={event=>{setOverview(null);setPeriodId(event.target.value);}}>{periods.map(period=><option key={period.id} value={period.id}>{period.label} · {formatDate(period.starts_on)} a {formatDate(period.ends_on)}</option>)}</select></label></header>
    <nav className="flex flex-wrap gap-2" aria-label="Espacios de Evaluar">{([["student","Evaluación del bimestre"],["family","Informe a familias"],["consolidated","Consolidado"]] as const).map(([target,label])=><Button key={target} variant={view===target||view==="conclusions"&&target==="student"?"default":"outline"} onClick={()=>setView(target)}>{label}</Button>)}</nav>
    {message&&<p role="status" className="text-sm">{message}</p>}
    {overviewError&&<p role="alert">{overviewError}<Button variant="outline" onClick={()=>setOverviewRetry(value=>value+1)}>Reintentar</Button></p>}
    {!overview&&!overviewError&&<p role="status">Cargando evaluación…</p>}
    {overview&&<>
      {overview.closure.closed&&<section className="space-y-3 rounded-xl bg-[#edf5fa] p-4"><h2 className="font-bold">Bimestre cerrado</h2><p className="text-sm">Para corregir la evaluación, reabre explícitamente el bimestre. Se conservarán el cierre anterior y el motivo de los cambios.</p><label className="block text-sm font-semibold">Motivo de reapertura<Textarea className="mt-1" value={reopenReason} onChange={event=>setReopenReason(event.target.value)}/></label><Button variant="outline" disabled={busy||!reopenReason.trim()} onClick={()=>void act(async()=>{await api("/api/period-evaluations/reopen",{classroomId,periodId,expectedCurrentVersionId:overview.closure.current_version_id,reason:reopenReason});setReopenReason("");await reloadOverview();setMessage("Bimestre reabierto. Los cambios quedarán registrados.");})}>Reabrir bimestre</Button></section>}
      {(view==="student"||view==="conclusions")&&<CompetencyPeriodReview key={`${classroomId}:${periodId}`} classroomId={classroomId} periodId={periodId} students={overview.students} scope={overview.scope} rows={overview.rows} closed={overview.closure.closed} initialStudentId={reviewPair.studentId} initialCompetencyId={reviewPair.competencyId} onChanged={reloadOverview} onContinue={()=>setView("family")}/>}
      {view==="family"&&<PeriodBatchPanel key={`${classroomId}:${periodId}:family`} classroomId={classroomId} periodId={periodId} kind="family" students={overview.students} competencies={overview.scope} disabled={overview.closure.closed} onSaved={reloadOverview} onContinue={()=>setView("consolidated")}/>}
      {view==="consolidated"&&<><PeriodConsolidated classroomId={classroomId} periodId={periodId} periodLabel={currentPeriod?.label??""} onReview={(student,competency)=>{setReviewPair({studentId:student,competencyId:competency});setStudentId(student);setCompetencyId(competency);setView("student");}}/>
        <p className="text-sm text-[#526b87]">El cierre conserva una versión de las valoraciones, conclusiones y pendientes sin evidencia. No asigna notas a competencias sin sustento.</p>
        <Button disabled={busy||!closureReady||overview.closure.closed} onClick={()=>void act(async()=>{await api("/api/period-evaluations/close",{classroomId,periodId,expectedCurrentVersionId:overview.closure.current_version_id,expectedSourceFingerprint:overview.closure.source_fingerprint});await reloadOverview();setMessage("Bimestre cerrado. Su versión quedó guardada.");})}>{overview.closure.closed?"Bimestre cerrado":"Cerrar bimestre"}</Button>
      </>}
      <details><summary className="min-h-11 cursor-pointer py-3 text-sm font-semibold text-[#07576c]">Herramientas de apoyo</summary><div className="flex flex-wrap gap-2"><Button variant="outline" onClick={()=>setView("classroom")}>Alcance y revisión avanzada</Button><Button variant="outline" onClick={()=>setView("coverage")}>Cobertura</Button></div></details>
    </>}
  </section>;
  const studentPicker = overview && <details open={focus !== "conclusion" || !selectedStudent} className={focus === "conclusion" ? "order-2 text-sm" : "rounded-2xl border bg-white p-3"}><summary className="min-h-11 cursor-pointer py-2 text-sm font-semibold text-[#07576c]">{selectedStudent ? studentName(selectedStudent) : "Seleccionar niño"} · Cambiar niño</summary><h2 className="px-2 py-2 font-bold">Niños</h2><div className="space-y-1">{overview.students.map((student) => { const complete = overview.scope.length > 0 && overview.scope.every((item) => overview.rows.some((row) => row.student_id === student.id && row.competency_id === item.id && row.state === "confirmed")); return <button key={student.id} type="button" aria-pressed={studentId === student.id} onClick={() => setStudentId(student.id)} className={`flex min-h-11 w-full items-center justify-between rounded-xl px-3 text-left text-sm ${studentId === student.id ? "bg-[#e8f6fb] font-bold text-[#07516a]" : "hover:bg-[#f4f8fb]"}`}>{studentName(student)}{complete && <Check className="size-4 text-green-700" />}</button>; })}</div></details>;
  const competencyPicker = <details open={focus !== "conclusion" || !selectedCompetency} className={focus === "conclusion" ? "order-2 text-sm" : "rounded-2xl border bg-white p-4"}><summary className="min-h-11 cursor-pointer py-2 text-sm font-semibold text-[#07576c]">Elegir competencia</summary><div><h2 className="text-lg font-bold">{selectedStudent ? `Revisar a ${studentName(selectedStudent)}` : "Selecciona un niño"}</h2><p className="mt-1 text-sm text-[#526b87]">Elige una competencia y revisa sus evidencias del período.</p><div className="mt-4 grid gap-2 sm:grid-cols-2">{studentRows.map((row) => <button key={row.competency_id} type="button" aria-pressed={competencyId === row.competency_id} onClick={() => setCompetencyId(row.competency_id)} className={`min-h-20 rounded-xl border p-3 text-left ${competencyId === row.competency_id ? "border-[#087d96] bg-[#eaf7fb]" : "bg-white hover:bg-[#f5f9fc]"}`}><b className="block text-sm">{row.competency_name}</b><span className="mt-1 block text-xs text-[#526b87]">{periodEvidenceLabel(row.evidence_count)}{row.state === "no_evidence" ? "" : ` · ${stateText[row.state] ?? row.state}`}</span></button>)}</div>{!studentRows.length && <p className="mt-3 text-sm">Aún no hay competencias previstas para este período. Revisa las actividades o añade una competencia en “Revisar aula”.</p>}</div></details>;
  return <section className="space-y-5">
    <div className="rounded-2xl border bg-white p-4 sm:p-5"><h1 className="text-2xl font-bold">{view === "conclusions" || focus === "conclusion" ? "Conclusiones" : "Evaluación del período"}</h1><p className="mt-1 text-sm text-[#526b87]">{view === "conclusions" || focus === "conclusion" ? "Revisa la conclusión basada en la valoración que confirmaste." : "Revisa lo observado y confirma una valoración por niño y competencia."}</p>
      <details className="mt-3 text-sm"><summary className="min-h-11 cursor-pointer py-2 font-semibold text-[#07576c]">{workspace.classrooms.find((item) => item.id === classroomId)?.section || "Aula"} · {workspace.years.find((item) => item.id === yearId)?.year || "Año escolar"}</summary><div className="mt-2 grid gap-3 sm:grid-cols-2">
        <label className="text-sm font-semibold">Año escolar<select className="mt-1 block min-h-11 w-full rounded-xl border bg-white px-3" value={yearId} onChange={(event) => { const id = event.target.value; setOverview(null); setOverviewError(""); setDetail(null); setYearId(id); setClassroomId(workspace.classrooms.find((item) => item.school_year_id === id)?.id ?? ""); setPeriodId(workspace.periods.find((item) => item.school_year_id === id)?.id ?? ""); }}><option value="">Selecciona un año</option>{workspace.years.map((item) => <option key={item.id} value={item.id}>{item.year}</option>)}</select></label>
        <label className="text-sm font-semibold">Aula<select className="mt-1 block min-h-11 w-full rounded-xl border bg-white px-3" value={classroomId} onChange={(event) => { setOverview(null); setOverviewError(""); setDetail(null); setClassroomId(event.target.value); }}><option value="">Selecciona un aula</option>{classrooms.map((item) => <option key={item.id} value={item.id}>{item.section} · {item.age} años</option>)}</select></label>
      </div></details><div className="mt-3"><label className="text-sm font-semibold">Período<select className="mt-1 block min-h-11 w-full rounded-xl border bg-white px-3" value={periodId} onChange={(event) => { setOverview(null); setOverviewError(""); setDetail(null); setPeriodId(event.target.value); }}><option value="">Selecciona un período</option>{periods.map((item) => <option key={item.id} value={item.id}>{item.label} · {formatDate(item.starts_on)} a {formatDate(item.ends_on)}</option>)}</select></label>
      </div>
      {periods.length > 0 && <details className="mt-3 text-sm"><summary className="cursor-pointer font-semibold text-[#087d96]">Organización de períodos</summary><p className="mt-2 text-[#526b87]">Este año está organizado por {periods[0].kind === "bimester" ? "bimestres" : "trimestres"}. Puedes cambiarlo antes de registrar evaluaciones.</p><Button className="mt-2" size="sm" variant="outline" disabled={busy} onClick={() => void act(async () => { const result = await api<{ periods: Period[] }>("/api/period-evaluations/configure", { yearId, kind: periods[0].kind === "bimester" ? "trimester" : "bimester" }); setWorkspace({ ...workspace, periods: [...workspace.periods.filter((item) => item.school_year_id !== yearId), ...result.periods] }); setPeriodId(result.periods[0]?.id ?? ""); })}>Cambiar a {periods[0].kind === "bimester" ? "trimestres" : "bimestres"}</Button></details>}
    </div>
    {message && <p role="status" className="rounded-xl bg-[#eaf7fb] px-4 py-3 text-sm text-[#17475d]">{message}</p>}
    {!overview ? overviewError ? <div role="alert" className="rounded-2xl border bg-white p-5"><p>No se pudieron cargar los registros. {overviewError}</p><Button className="mt-3" variant="outline" onClick={() => { setOverviewError(""); setOverviewRetry((count) => count + 1); }}>Reintentar</Button></div> : <p>{classroomId && periodId ? "Cargando registros…" : "Selecciona un aula y un período para comenzar."}</p> : <>
      {(overview.progress.observation_pending + overview.progress.review_pending) > 0 && <p className="rounded-xl bg-[#fff2d9] px-4 py-3 text-sm">{overview.progress.observation_pending} pares niño–competencia pendientes de observación o información suficiente y {overview.progress.review_pending} con evidencia pendiente de revisión docente. Se conservarán sin letra para próximas oportunidades; el cierre anual exigirá resolverlos.</p>}
      {view === "consolidated" && <PeriodConsolidated key={`${classroomId}:${periodId}`} classroomId={classroomId} periodId={periodId} periodLabel={currentPeriod?.label ?? "Período"} onReview={(student, competency) => { setStudentId(student); setCompetencyId(competency); setView("student"); }} />}
      {view === "conclusions" && <section className="rounded-2xl border bg-white p-5"><h2 className="text-xl font-bold">Conclusiones descriptivas · {currentPeriod?.label}</h2>
        <p className="mt-2 text-sm">Cada conclusión se prepara desde una valoración docente vigente. Revisa el texto antes de confirmarlo.</p>
        {overview.rows.some((row) => row.state === "conclusion_pending" || row.state === "confirmed") ? <div className="mt-3 space-y-2">{overview.rows.filter((row) => row.state === "conclusion_pending" || row.state === "confirmed").map((row) => <Button key={`${row.student_id}:${row.competency_id}`} className="h-auto min-h-11 w-full justify-start whitespace-normal py-3 text-left" variant="outline" onClick={() => { setStudentId(row.student_id); setCompetencyId(row.competency_id); setFocus("conclusion"); setView("student"); }}>{studentName(overview.students.find((student) => student.id === row.student_id)!)} · {row.competency_name} · {row.conclusion ? "Ver conclusión" : "Preparar conclusión"}</Button>)}</div>
          : overview.rows.length ? <p className="mt-3 text-sm">Confirma una valoración para preparar su conclusión.</p> : null}
        {overview.rows.some((row) => row.state !== "confirmed" && row.state !== "conclusion_pending") && <p className="mt-3 text-sm">Hay valoraciones pendientes. Sus conclusiones estarán disponibles después de confirmarlas.</p>}
        {overview.rows.length ? <Button className="mt-3" variant="outline" onClick={() => { const next = overview.rows.find((row) => row.state !== "confirmed" && row.state !== "conclusion_pending"); if (next) { setStudentId(next.student_id); setCompetencyId(next.competency_id); } setFocus("none"); setView("student"); }}>Completar valoraciones</Button> : <><p className="mt-3 text-sm">Aún no hay competencias trabajadas en este período. Prepara una actividad y registra lo observado para poder valorarlas.</p>{onPrepareActivity && <Button className="mt-3 min-h-11" onClick={onPrepareActivity}>Preparar actividad</Button>}</>}
      </section>}
      {view === "coverage" && <PedagogicalCoverage key={`${classroomId}:${periodId}`} classroomId={classroomId} periodId={periodId} onPlan={onPlan} onPrepareActivity={onPrepareActivity} onReview={(student, competency) => { setStudentId(student); setCompetencyId(competency); setView("student"); }} />}
      {view === "family" && currentPeriod && <FamilyReportGenerator key={`${classroomId}:${periodId}`} classroomId={classroomId} period={currentPeriod} students={overview.students.map((student) => ({ id:student.id,name:studentName(student) }))} initialStudentId={studentId} onConclusion={(id) => { setStudentId(id); setView("student"); }} />}
      {view === "student" && focus === "conclusion" && <Button variant="ghost" className="min-h-11 justify-start" onClick={() => { setFocus("none"); setView("conclusions"); }}>← Conclusiones de {currentPeriod?.label}</Button>}
      {view === "student" && <div className={`gap-5 ${focus === "conclusion" ? "flex flex-col" : "grid lg:grid-cols-[240px_1fr]"}`}>
        {focus !== "conclusion" && studentPicker}
        <div className="flex min-w-0 flex-col gap-4">{focus !== "conclusion" && competencyPicker}
          {selectedCompetency && detail && detail.classroom_id === classroomId && detail.period_id === periodId && detail.student_id === studentId && detail.competency_id === competencyId && <article className="rounded-2xl border bg-white p-4 sm:p-5">{focus === "conclusion" && selectedStudent && <p className="mb-2 text-sm font-semibold text-[#087d96]">{studentName(selectedStudent)} · {currentPeriod?.label}</p>}<div className="flex flex-wrap items-start justify-between gap-2"><div><h2 className="text-lg font-bold">{selectedCompetency.name}</h2><p className="mt-1 text-sm text-[#526b87]">{periodEvidenceLabel(detail.evidence_count)}{detail.state === "no_evidence" ? "" : ` · ${stateText[detail.state] ?? detail.state}`}</p>{detail.diagnostic_antecedents.length > 0 && <p className="mt-1 text-sm text-[#526b87]">{diagnosticAntecedentLabel(detail.diagnostic_antecedents.length)} {detail.diagnostic_antecedents.length === 1 ? "disponible" : "disponibles"} como contexto.</p>}</div>{detail.state === "confirmed" && <span className="rounded-full bg-[#e6f9ef] px-3 py-1 text-sm font-semibold text-green-800">✓ Confirmada</span>}</div>
            {detail.state === "needs_review" && <p className="mt-4 rounded-xl bg-[#fff2d9] p-3 text-sm">Hay observaciones nuevas o modificadas. Revisa el sustento y confirma una nueva versión.</p>}
            <details open={!assessmentReadOnly} className="mt-3 text-sm"><summary className="min-h-11 cursor-pointer py-2 font-semibold text-[#07576c]">Estado de evidencia y decisión docente</summary>            {detail.assessment?.details?.information_status && <p className="mt-4 rounded-xl bg-[#f2f8fb] p-3 text-sm"><b>Estado de evidencia:</b> {detail.assessment.details.information_status === "insufficient" ? "Insuficiente" : "Suficiente"}{detail.assessment.details.information_status === "insufficient" && detail.assessment.details.insufficiency_reason ? ` · ${detail.assessment.details.insufficiency_reason}` : ""}</p>}
            {detail.state === "insufficient_information" && detail.insufficiency_reason && <p className="mt-4 rounded-xl bg-[#fff2d9] p-3 text-sm">Evidencia insuficiente en este borrador: {detail.insufficiency_reason}</p>}
            {detail.assessment?.teacher_justification && <p className="mt-4 rounded-xl bg-[#f2f8fb] p-3 text-sm"><b>Motivo de la decisión docente:</b> {detail.assessment.teacher_justification}</p>}
</details>
              {assessmentReadOnly&&<section id="period-conclusion" tabIndex={-1} className="mt-4 rounded-xl bg-[#f4f8fb] p-4 [&_button]:min-h-11 [&_button]:h-auto [&_button]:whitespace-normal [&_button]:py-3">
                <h3 className="font-bold">Conclusión descriptiva</h3>
                <p className="mt-1 text-sm text-[#526b87]">{detail.conclusion && !conclusionGenerationId && !writingConclusion ? "Conclusión confirmada · solo lectura." : "Ayni puede proponerte un texto. También puedes escribirlo tú. Revísalo antes de confirmar."}</p>
                <p className="mt-2 text-sm"><b>Valoración docente:</b> {detail.assessment?.achievement_level}</p>
                {!detail.conclusion&&<div className="mt-3 flex flex-wrap gap-2">
                  <Button variant="outline" disabled={busy} onClick={()=>void act(async()=>{const result=await api<{generation_id:string;proposal:ConclusionProposal}>("/api/period-evaluations/conclusion/suggest",{classroomId,periodId,studentId,competencyId});setWritingConclusion(false);setConclusionGenerationId(result.generation_id);setConclusionProposal(result.proposal);setConclusionText(result.proposal.conclusion_text);setMessage("Conclusión preparada. Revísala antes de confirmar.");})}><Sparkles className="mr-2 size-4"/>Preparar con Ayni</Button>
                  <Button variant="outline" disabled={busy} onClick={()=>{setWritingConclusion(true);setConclusionGenerationId("");setConclusionProposal(null);setConclusionText("");setMessage("");}}>Escribir yo</Button>
                </div>}
                {(writingConclusion||conclusionGenerationId||detail.conclusion)&&<>{detail.conclusion&&!conclusionGenerationId&&!writingConclusion ? <p className="mt-3 whitespace-pre-wrap text-sm text-[#173352]">{conclusionText}</p> : <Textarea aria-label="Texto de la conclusión descriptiva" className="mt-3 min-h-24" value={conclusionText} onChange={(event)=>setConclusionText(event.target.value)} disabled={Boolean(detail.conclusion&&!conclusionGenerationId&&!writingConclusion)} placeholder="Describe solo lo sustentado por las observaciones. Si falta información, indícalo."/>}
                  {writingConclusion&&<Button className="mt-3" disabled={busy||!conclusionText.trim()} onClick={()=>void act(async()=>{await api("/api/period-evaluations/conclusion/confirm",{classroomId,periodId,studentId,competencyId,manualText:conclusionText});await reloadOverview();await reloadDetail();setMessage("Conclusión escrita y confirmada por ti.");})}>Confirmar mi conclusión</Button>}
                  {conclusionGenerationId&&conclusionProposal&&<Button className="mt-3" disabled={busy||!conclusionText.trim()} onClick={()=>void act(async()=>{await api("/api/period-evaluations/conclusion/confirm",{classroomId,periodId,studentId,competencyId,generationId:conclusionGenerationId,proposal:{...conclusionProposal,conclusion_text:conclusionText}});setConclusionGenerationId("");setConclusionProposal(null);await reloadOverview();await reloadDetail();setMessage("Conclusión confirmada.");})}>Confirmar conclusión</Button>}
                </>}
              </section>}
            <button type="button" onClick={() => setShowSustento(!showSustento)} className="mt-4 flex min-h-11 w-full items-center justify-between rounded-xl border bg-[#f5f9fc] px-4 text-left font-semibold text-[#07516a]">Ver sustento <ChevronDown className={`size-4 ${showSustento ? "rotate-180" : ""}`} /></button>
            {showSustento && <div className="mt-3 space-y-4"><section className="rounded-xl bg-[#f2f8fb] p-4 text-sm">{detail.reference.kind === "official" ? <><b>Desempeño específico de la edad</b>{detail.reference.items.map((item) => <p key={item.id} className="mt-1">{item.official_text}</p>)}</> : <><b>{detail.reference.competency}</b><p className="mt-1">Capacidades: {detail.reference.capacities.join("; ")}</p><p className="mt-1">Estándar del ciclo II (síntesis): {detail.reference.standard_summary}</p><p className="mt-1 font-semibold">Desempeño específico para esta edad: inexistente en la referencia disponible. Las actuaciones se muestran en los registros de abajo.</p></>}</section><section><h3 className="font-bold">Antecedentes diagnósticos</h3><p className="text-sm text-[#526b87]">Sirven como contexto; no se cuentan como evidencias para la valoración de este período.</p>{detail.diagnostic_antecedents.length ? <ul className="mt-2 space-y-2">{detail.diagnostic_antecedents.map((item) => <li key={`${item.source_type}:${item.id}`} className="rounded-xl border p-3 text-sm"><b>{formatDate(item.observed_on)} · {item.situation_title}</b>{item.criterion_text && <p className="mt-1 text-[#526b87]">{item.criterion_text}</p>}<p className="mt-1">{item.observation_text || "Observación diagnóstica sin nota escrita."}</p></li>)}</ul> : <p className="mt-2 text-sm">Sin antecedentes diagnósticos registrados.</p>}</section><section><h3 className="font-bold">Evidencias de este período</h3>{detail.timeline.length ? <ul className="mt-2 space-y-3">{detail.timeline.map((item) => <li key={item.id} className="rounded-xl border p-4 text-sm"><b>{formatDate(item.observed_on)} · {item.activity_title}</b><p className="mt-1 text-[#526b87]">Criterio: {item.criterion_text}</p><p className="mt-2">{item.observation_text || "Se adjuntó una evidencia visual; no hay nota escrita."}</p>{item.media_available && <a className="mt-2 inline-block font-semibold text-[#087d96] underline" target="_blank" rel="noreferrer" href={`${localDatabaseApiUrl}/api/period-evaluations/evidence/${item.id}/media`}>Abrir evidencia adjunta</a>}</li>)}</ul> : <p className="mt-2 text-sm">Aún no hay evidencias registradas en este período.</p>}</section></div>}
            <div className="mt-5 border-t pt-5"><details open={focus !== "conclusion" || !assessmentReadOnly}><summary className="min-h-11 cursor-pointer py-2 font-semibold text-[#07576c]">Revisar la valoración del período</summary><h3 className="font-bold">Tu valoración del período</h3><p className="mt-1 text-sm text-[#526b87]">El nivel se refiere al conjunto de registros. Ninguna observación individual recibe una nota.</p>
              {assessmentReadOnly&&<Button className="mt-4" variant="outline" disabled={busy || !detail.evidence_count} onClick={()=>void act(async()=>{await api("/api/period-evaluations/save-draft",{classroomId,periodId,studentId,competencyId,evidenceFingerprint:detail.evidence_fingerprint,expectedDraftRevision:null,provisionalLevel:detail.assessment?.achievement_level,teacherAnalysis:detail.assessment?.details?.evidence_overview??"",conclusionText:"",teacherJustification:detail.assessment?.teacher_justification??""});await reloadOverview();await reloadDetail();setMessage("Revisión iniciada. La valoración anterior se conserva en el historial; guarda y confirma los cambios.");})}>Revisar valoración</Button>}
              <Button className="mt-4" variant="outline" disabled={busy || detail.evidence_count === 0 || !assessmentMasterReady || assessmentReadOnly} onClick={() => void act(async () => { const result = await api<Suggestion>("/api/period-evaluations/suggest", { classroomId, periodId, studentId, competencyId }); setSuggestion(result); setTeacherAnalysis(result.analysis.evidence_overview); setConclusionText(""); setAchievementLevel(""); setTeacherJustification(""); setSavedDraftSnapshot(formSnapshot(result.analysis.evidence_overview,"","","")); await reloadOverview(); await reloadDetail(); setMessage(result.analysis.information_status === "insufficient" ? "Ayni encontró información insuficiente. Puedes seguir observando o explicar tu decisión docente." : "Análisis listo. Revisa las evidencias y elige tú la valoración."); })}><Sparkles className="mr-2 size-4" /> Analizar evidencias</Button>
              {!assessmentMasterReady&&<p className="mt-2 text-sm text-[#526b87]">Confirma primero el marco de evaluación del período.</p>}
              {suggestion?.analysis.information_status === "insufficient" && <p className="mt-3 rounded-xl bg-[#fff2d9] p-3 text-sm">Información insuficiente: {suggestion.analysis.insufficiency_reason}</p>}
              <label className="mt-4 block text-sm font-semibold">¿Qué muestran las observaciones?<Textarea className="mt-1 min-h-24" value={teacherAnalysis} readOnly={assessmentReadOnly} onChange={(event) => setTeacherAnalysis(event.target.value)} placeholder="Ej.: En distintos juegos explicó sus ideas y pidió ayuda cuando la necesitó." /></label>
              {!assessmentReadOnly&&<label className="mt-4 block text-sm font-semibold">Valoración que confirmas<select className="mt-1 block min-h-11 w-full rounded-xl border bg-white px-3" value={achievementLevel} onChange={(event) => setAchievementLevel(event.target.value)}><option value="">Elige después de revisar</option><option value="AD">AD · Logro destacado</option><option value="A">A · Logro esperado</option><option value="B">B · En proceso</option><option value="C">C · En inicio</option></select></label>}
              {(detail.evidence_count < AYNI_HEURISTICS.assessment_low_records_for_explanation || suggestion?.analysis.information_status === "insufficient") && !assessmentReadOnly && <label className="mt-4 block text-sm font-semibold">Explica el criterio de tu decisión<Textarea className="mt-1 min-h-20" value={teacherJustification} onChange={(event) => setTeacherJustification(event.target.value)} placeholder="¿Qué sustento te permite tomar esta decisión?" /></label>}
              {detail.draft && !detail.draft.current && <p className="mt-3 rounded-xl bg-[#fff2d9] p-3 text-sm">Las observaciones cambiaron desde este borrador. Revisa lo nuevo y guarda otra vez; la sugerencia anterior no se usará.</p>}
              {!assessmentReadOnly&&<div className="mt-4 flex flex-wrap gap-2"><Button variant="outline" disabled={busy} onClick={() => void act(async () => { await api("/api/period-evaluations/save-draft", { classroomId, periodId, studentId, competencyId, evidenceFingerprint: detail.evidence_fingerprint, expectedDraftRevision:detail.draft?.revision??null, provisionalLevel: achievementLevel || null, teacherAnalysis, conclusionText:"", teacherJustification }); await reloadOverview(); await reloadDetail(); setMessage("Borrador guardado. Puedes salir y volver más tarde."); })}>Guardar borrador</Button>
              <Button disabled={busy || hasUnsavedDraft || !detail.evidence_count || !achievementLevel || !teacherAnalysis.trim()} onClick={() => void act(async () => { await api("/api/period-evaluations/confirm", { classroomId, periodId, studentId, competencyId, evidenceFingerprint: detail.evidence_fingerprint, expectedDraftRevision:detail.draft?.revision??null, achievementLevel, teacherAnalysis, conclusionText:"", teacherJustification }); await reloadOverview(); await reloadDetail(); setMessage("Valoración confirmada por ti. Ahora prepara la conclusión descriptiva."); })}>Confirmar valoración <ArrowRight className="ml-2 size-4" /></Button></div>}{!assessmentReadOnly&&hasUnsavedDraft && <p className="mt-2 text-sm text-[#526b87]">Guarda los cambios antes de confirmar.</p>}
            </details></div>
          </article>}
          {focus === "conclusion" && competencyPicker}
        </div>
        {focus === "conclusion" && studentPicker}
      </div>}
      {view === "classroom" && <div className="space-y-4"><div className="rounded-2xl border bg-white p-5"><h2 className="text-lg font-bold">Revisar aula · {currentPeriod?.label}</h2><p className="mt-1 text-sm text-[#526b87]">Aparecen también las competencias previstas sin observaciones.</p><div className="mt-4 flex flex-wrap gap-2">{overview.scope.map((item) => <span key={item.id} className="rounded-full bg-[#eaf7fb] px-3 py-2 text-sm">{item.name}</span>)}</div>
          <details className="mt-4"><summary className="cursor-pointer font-semibold text-[#087d96]">Ajustar competencias trabajadas</summary><div className="mt-3 flex flex-wrap gap-2"><select aria-label="Competencia para incluir" className="min-h-11 flex-1 rounded-xl border bg-white px-3" value={addingCompetencyId} onChange={(event) => setAddingCompetencyId(event.target.value)}><option value="">Elige una competencia</option>{missing.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select><Button disabled={busy || !addingCompetencyId} onClick={() => void act(async () => { await api("/api/period-evaluations/scope", { classroomId, periodId, competencyId: addingCompetencyId, included: true }); setAddingCompetencyId(""); await reloadOverview(); })}>Añadir</Button></div><p className="mt-3 text-sm">Si una competencia prevista no se trabajó ni evaluó en este período, puedes retirarla con una explicación.</p><select aria-label="Competencia para retirar" className="mt-2 min-h-11 w-full rounded-xl border bg-white px-3" value={excludingId} onChange={(event) => setExcludingId(event.target.value)}><option value="">Elige una competencia para retirar</option>{overview.scope.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select>{excludingId && <><Textarea className="mt-2" value={exclusionReason} onChange={(event) => setExclusionReason(event.target.value)} placeholder="¿Por qué no se desarrolló ni evaluó en este período?" /><Button variant="outline" className="mt-2" disabled={busy || !exclusionReason.trim()} onClick={() => void act(async () => { await api("/api/period-evaluations/scope", { classroomId, periodId, competencyId: excludingId, included: false, reason: exclusionReason }); setExcludingId(""); setExclusionReason(""); await reloadOverview(); })}>Retirar de este período</Button></>}</details>
        </div>
        <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-4">
          <select aria-label="Filtrar por niño" className="min-h-11 rounded-xl border bg-white px-3" value={classroomStudentFilter} onChange={(event) => setClassroomStudentFilter(event.target.value)}><option value="">Todos los niños</option>{overview.students.map((item) => <option key={item.id} value={item.id}>{studentName(item)}</option>)}</select>
          <select aria-label="Filtrar por competencia" className="min-h-11 rounded-xl border bg-white px-3" value={classroomCompetencyFilter} onChange={(event) => setClassroomCompetencyFilter(event.target.value)}><option value="">Todas las competencias</option>{overview.scope.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select>
          <select aria-label="Filtrar por área" className="min-h-11 rounded-xl border bg-white px-3" value={classroomAreaFilter} onChange={(event)=>setClassroomAreaFilter(event.target.value)}><option value="">Todas las áreas</option>{classroomAreas.map((area)=><option key={area}>{area}</option>)}</select>
          <select aria-label="Filtrar por estado" className="min-h-11 rounded-xl border bg-white px-3" value={classroomStatusFilter} onChange={(event) => setClassroomStatusFilter(event.target.value)}><option value="">Todos los estados</option><option value="pending">Pendientes</option><option value="complete">Completas</option></select>
        </div>
        <div className="max-h-[65vh] overflow-auto rounded-2xl border bg-white"><table className="min-w-max border-separate border-spacing-0 text-sm"><thead className="sticky top-0 z-20 bg-[#eaf7fb]"><tr><th className="sticky left-0 z-30 min-w-48 border-b bg-[#eaf7fb] p-3 text-left">Niño</th>{visibleScope.map((scope)=>{const sample=overview.rows.find((row)=>row.competency_id===scope.id);return <th key={scope.id} title={`${sample?.competency_name??scope.name} · ${sample?.area??""}`} className="min-w-28 border-b p-3 text-center"><span className="block">{sample?.short_label??scope.name}</span><small className="font-normal text-[#526b87]">{sample?.area}</small></th>;})}</tr></thead><tbody>{visibleStudents.map((student)=><tr key={student.id}><th className="sticky left-0 z-10 border-b bg-white p-3 text-left">{studentName(student)}</th>{visibleScope.map((scope)=>{const row=overview.rows.find((item)=>item.student_id===student.id&&item.competency_id===scope.id);const hidden=classroomStatusFilter&&(classroomStatusFilter==="complete"?row?.state!=="confirmed":row?.state==="confirmed");return <td key={scope.id} className={`border-b p-2 text-center ${row?.state==="needs_review"?"bg-[#fff2d9]":""}`}><button title={row?`${stateText[row.state]??row.state} · ${row.evidence_count} evidencias`:"Sin registro"} className={`min-h-10 min-w-12 rounded-lg px-3 font-bold ${hidden?"opacity-20":row?.level?"bg-[#e7f7ef] text-green-800":"bg-[#f3f6f9] text-[#66758d]"}`} onClick={()=>{if(!row)return;setStudentId(student.id);setCompetencyId(scope.id);setView("student");}}>{row?.level??"—"}</button></td>;})}</tr>)}</tbody></table></div>
        {overview.closure.closed && !overview.closure.current && <p className="rounded-xl bg-[#fff2d9] p-4 text-sm">Se añadieron o modificaron registros después del cierre. Revisa las valoraciones y vuelve a cerrar.</p>}
        <Button disabled={busy || !closureReady || (overview.closure.closed && overview.closure.current)} onClick={() => void act(async () => { await api("/api/period-evaluations/close", { classroomId, periodId,expectedCurrentVersionId:overview.closure.current_version_id,expectedSourceFingerprint:overview.closure.source_fingerprint }); await reloadOverview(); setMessage("Período cerrado. Las valoraciones confirmadas y los pendientes de observación quedaron diferenciados."); })}>{overview.closure.closed && overview.closure.current ? "✓ Período cerrado" : "Cerrar período"}</Button>
        <Button variant="outline" onClick={() => { setFocus("none"); setView("consolidated"); }}>Ver consolidado del período</Button>
        <section className="rounded-2xl border bg-white p-5"><h2 className="font-bold">Resumen del aula</h2><p className="mt-1 text-sm text-[#526b87]">Los números se calculan desde las valoraciones confirmadas y las observaciones del período.</p><div className="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><div className="rounded-xl bg-[#eaf7fb] p-3"><b>{overview.statistics.competencies.filter((item)=>["worked","evidenced"].includes(item.state)).length}</b><p className="text-sm">competencias trabajadas</p></div><div className="rounded-xl bg-[#eff8f2] p-3"><b>{overview.statistics.classroom.confirmed_assessments}</b><p className="text-sm">valoraciones confirmadas</p></div><div className="rounded-xl bg-[#fff2d9] p-3"><b>{overview.statistics.classroom.pending_assessments}</b><p className="text-sm">valoraciones pendientes</p></div><div className="rounded-xl bg-[#f1eafd] p-3"><b>{overview.statistics.competencies.filter((item)=>item.students_without_evidence>0).length}</b><p className="text-sm">competencias con cobertura incompleta</p></div></div><details className="mt-4 rounded-xl border bg-white p-3"><summary className="cursor-pointer font-semibold text-[#087d96]">Ver estadísticas por competencia</summary><div className="mt-3 grid gap-3 md:grid-cols-2">{overview.statistics.competencies.map((item)=><article key={item.competency_id} className="rounded-xl bg-[#f4f8fb] p-3"><div className="flex items-start justify-between gap-3"><div><b>{item.short_label}</b><p className="text-xs text-[#526b87]">{item.area}</p></div><span className="text-xs font-semibold text-[#526b87]">{item.evidence_coverage}% con evidencia</span></div><div className="mt-3 grid grid-cols-4 gap-1 text-center text-xs">{(["AD","A","B","C"] as const).map((level)=><div key={level} className="rounded-lg bg-white px-1 py-2"><b className="block">{item.levels[level]??0}</b>{level}</div>)}</div><div className="mt-3 h-2 overflow-hidden rounded-full bg-[#dbe6ef]"><div className="h-full rounded-full bg-[#0d8aa3]" style={{width:`${Math.min(100,item.evidence_coverage)}%`}} /></div><p className="mt-2 text-xs text-[#526b87]">{item.activity_count} actividades · {item.criterion_count} criterios · {item.evidence_count} evidencias</p></article>)}</div></details><div className="mt-4 flex flex-wrap gap-2"><Button variant="outline" onClick={()=>void act(async()=>setClassroomReport(await api(`/api/period-evaluations/classroom-report?classroomId=${classroomId}&periodId=${periodId}`)))}>Ver informe del aula</Button>{!newAyniFeatureEnabled()&&<Button disabled={busy||overview.statistics.classroom.confirmed_assessments<Math.ceil(overview.statistics.classroom.total_assessments/2)} onClick={()=>void act(async()=>{const result=await api<{generation_id:string;proposal:ClassroomReportDetails}>("/api/period-evaluations/classroom-report/generate",{classroomId,periodId});setClassroomReport(result);setMessage("Informe preparado. Revísalo y confírmalo.");})}>Preparar informe del aula</Button>}</div>{classroomReport&&<div className="mt-4 rounded-xl bg-[#f4f8fb] p-4 text-sm">{(()=>{const report=classroomReport.proposal??classroomReport.current?.details;if(!report)return <p>Aún no hay informe.</p>;return <div className="space-y-3"><div><b>Panorama general</b><p>{report.general_overview}</p></div><div><b>Fortalezas del grupo</b><ul className="list-disc pl-5">{report.group_strengths.map((item)=><li key={item}>{item}</li>)}</ul></div><div><b>Aspectos para seguir desarrollando</b><ul className="list-disc pl-5">{report.competencies_needing_development.map((item)=><li key={item}>{item}</li>)}</ul></div><div><b>Cobertura de evidencias</b><p>{report.evidence_coverage}</p></div><div><b>Para el siguiente período</b><ul className="list-disc pl-5">{report.next_period_findings.map((item)=><li key={item}>{item}</li>)}</ul></div></div>;})()}{classroomReport.generation_id&&classroomReport.proposal&&<Button className="mt-3" onClick={()=>void act(async()=>{await api("/api/period-evaluations/classroom-report/confirm",{classroomId,periodId,generationId:classroomReport.generation_id,proposal:classroomReport.proposal});setClassroomReport(await api(`/api/period-evaluations/classroom-report?classroomId=${classroomId}&periodId=${periodId}`));await reloadOverview();setMessage("Informe del aula confirmado.");})}>Confirmar informe del aula</Button>}</div>}</section>
      </div>}
      {view === "report" && <div className="rounded-2xl border bg-white p-5"><h2 className="text-lg font-bold">Datos del Informe de Progreso</h2><p className="mt-1 text-sm text-[#526b87]">Se preparan desde las valoraciones confirmadas; el Word y PDF se añadirán con una plantilla posterior.</p>{overview.closure.closed && overview.closure.current ? <><label className="mt-4 block text-sm font-semibold">Niño<select className="mt-1 block min-h-11 w-full rounded-xl border bg-white px-3" value={studentId} onChange={(event) => { setStudentId(event.target.value); setReport(null); }}>{overview.students.map((item) => <option key={item.id} value={item.id}>{studentName(item)}</option>)}</select></label><Button className="mt-3" onClick={() => void act(async () => { const result = await api<{ competencies: Consolidated["rows"] }>(`/api/period-evaluations/progress-report?classroomId=${classroomId}&periodId=${periodId}&studentId=${studentId}`); setReport({ rows: result.competencies }); })}>Ver datos del informe</Button>{report && <ul className="mt-4 space-y-3">{report.rows.map((row) => <li key={row.competency_id} className="rounded-xl bg-[#f2f8fb] p-4"><b>{row.competency_name} · {row.achievement_level}</b><p className="mt-1 text-sm">{row.conclusion || "Sin conclusión opcional para AD."}</p></li>)}</ul>}</> : <p className="mt-4 rounded-xl bg-[#fff2d9] p-4 text-sm">Primero confirma las valoraciones y cierra el período en “Revisar aula”.</p>}</div>}
      <details className="text-sm"><summary className="min-h-11 cursor-pointer py-2 font-semibold text-[#07576c]">Otras vistas de evaluación</summary><div className="mt-2">      <div className="flex flex-wrap gap-2"><Button variant={view === "student" ? "default" : "outline"} aria-pressed={view === "student"} onClick={() => { setFocus("none"); setView("student"); }}>Revisar un niño</Button><Button variant={view === "classroom" ? "default" : "outline"} aria-pressed={view === "classroom"} onClick={() => { setFocus("none"); setView("classroom"); }}>Revisar aula</Button><Button variant={view === "consolidated" ? "default" : "outline"} aria-pressed={view === "consolidated"} onClick={() => { setFocus("none"); setView("consolidated"); }}>Consolidado</Button><Button variant={view === "coverage" ? "default" : "outline"} aria-pressed={view === "coverage"} onClick={() => { setFocus("none"); setView("coverage"); }}>Cobertura</Button><Button variant={view === "report" ? "default" : "outline"} aria-pressed={view === "report"} onClick={() => { setFocus("none"); setView("report"); }}>Informe de progreso</Button><Button variant={view === "family" ? "default" : "outline"} aria-pressed={view === "family"} onClick={() => { setFocus("none"); setView("family"); }}>Informe a familias</Button></div>
</div></details>
      <details className="rounded-xl border bg-white p-4"><summary className="min-h-11 cursor-pointer py-2 font-semibold">Progreso y pasos para cerrar {currentPeriod?.label}</summary><div className="mt-3 space-y-3">      {overview.progress.annual_unvalued !== null && overview.progress.annual_unvalued > 0 && <p className="rounded-xl bg-[#fff2d9] px-4 py-3 text-sm">El cierre anual requiere resolver {overview.progress.annual_unvalued} pares niño–competencia aplicables que aún no tienen una valoración docente vigente.</p>}
      <div className="grid gap-3 sm:grid-cols-2"><div className="rounded-2xl bg-[#eaf7fb] p-4"><b>{overview.progress.students_complete}/{overview.progress.students_total} niños con su período resuelto</b></div><div className="rounded-2xl bg-[#eff8f2] p-4"><b>{overview.statistics.classroom.confirmed_assessments}/{overview.statistics.classroom.total_assessments} valoraciones docentes registradas</b></div></div>
      <section className="rounded-2xl border bg-white p-5"><div className="flex flex-wrap items-center justify-between gap-2"><div><h2 className="font-bold">Cierre de {currentPeriod?.label}</h2><p className="text-sm text-[#526b87]">Continúa desde el primer paso pendiente.</p></div><b className="text-sm text-[#087d96]">{overview.closure_steps.filter((step)=>step.done).length}/8 pasos</b></div><ol className="mt-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-4">{overview.closure_steps.map((step)=><li key={step.number} className={`rounded-xl px-3 py-3 text-sm ${step.done?"bg-[#e8f7ef] text-green-800":"bg-[#f4f7fa] text-[#526b87]"}`}><b>{step.done?"✓":"○"} {step.label}</b></li>)}</ol></section>
</div></details>
    </>}
    {!newAyniFeatureEnabled()&&<details open={!assessmentMasterReady} className="rounded-xl border bg-white p-3"><summary className="min-h-11 cursor-pointer py-2 font-semibold text-[#07576c]">Marco del período · {assessmentMasterReady ? "Confirmado" : "Requiere preparación o revisión"}</summary>    {classroomId&&periodId&&<AssessmentMasterPanel key={`${classroomId}:${periodId}`} periodId={periodId} onReady={setAssessmentMasterReady}/>}
</details>}
  </section>;
}
